export const SITEMAP_XML: string = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url>\n    <loc>https://blog.radioindex.org</loc>\n    <changefreq>daily</changefreq>\n    <priority>1.0</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-flagship-detectives-and-westerns-solved</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-batch-2-lone-ranger-sherlock-holmes-sam-spade-solved</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n</urlset>";
export const JSON_FEED: string = "{\n  \"version\": \"https://jsonfeed.org/version/1.1\",\n  \"title\": \"RadioIndex Archival Journal\",\n  \"home_page_url\": \"https://blog.radioindex.org\",\n  \"feed_url\": \"https://blog.radioindex.org/feed.json\",\n  \"description\": \"Forensic OTR audio archaeology, neural speech models, and primary newspaper scan verification.\",\n  \"items\": [\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts\",\n      \"title\": \"Solving \\\"Date Unknown\\\" Radio Mysteries: Forensic Audio, Multi-Platform Transcripts & Primary Newspaper Scans\",\n      \"content_html\": \"<h2>The 76,000-Recording Challenge</h2>\\n\\n<p>In Old Time Radio (OTR) preservation, collector tapes have circulated for over half a century labeled with vague tags like <em>\\\"Date Unknown\\\"</em>, <em>\\\"The Part 19\\\"</em>, or completely blank titles. Across the 273,234 recordings in the RadioIndex source-of-record archive, <strong>76,321 recordings</strong> entered our catalog without verified calendar airdates.</p>\\n\\n<p>Today, we established a deterministic forensic discovery pipeline. What makes this approach definitive is the fusion of <strong>our multi-tier audio transcription ensemble</strong> (YouTube captions, Spreaker feeds, local neural Whisper ASR) with <strong>our vast collection of primary newspaper scans, daily radio highlight columns, and trade periodicals</strong>.</p>\\n\\n<p>When internal audio clues (character names, sponsor commercials, local station call letters) line up with the <strong>actual newspaper scans from the morning of the broadcast</strong>, we can confirm the exact historical transmission beyond all doubt.</p>\\n\\n<hr>\\n\\n<h2>The Multi-Source Audio Transcription Ensemble</h2>\\n\\n<p>Rather than relying on a single speech recognition pass, our archival pipeline ingests, correlates, and aligns dialogue from multiple complementary sources:</p>\\n\\n<pre><code class=\\\"language-text\\\">┌─────────────────────────────────────────────────────────────────────────┐\\n│                 MULTI-SOURCE SPEECH RECOGNITION ENSEMBLE                │\\n├───────────────────┬───────────────────┬─────────────────────────────────┤\\n│ YouTube Captions  │ Spreaker Transcripts│ Local Neural Whisper ASR      │\\n│ &amp; Archive Uploads │ &amp; Podcast Feeds   │ (Apple Silicon GPU / MLX)       │\\n└─────────┬─────────┴─────────┬─────────┴────────────────┬────────────────┘\\n          │                   │                          │\\n          └───────────────────┼──────────────────────────┘\\n                              ▼\\n        ┌───────────────────────────────────────────────┐\\n        │     Dialogue, Sponsor &amp; Cue Entity Matcher    │\\n        └─────────────────────┬─────────────────────────┘\\n                              │\\n                              ▼\\n┌─────────────────────────────────────────────────────────────────────────┐\\n│               PRIMARY NEWSPAPER &amp; NETWORK LOG VERIFICATION              │\\n├───────────────────────────────────┬─────────────────────────────────────┤\\n│ Morning Radio Grids &amp; Highlights  │ Jerry Haendiges (jjonez) &amp; Goldin   │\\n│ (NYT, Chicago Trib, LA Times, WP) │ Master Network Broadcast Logs       │\\n└───────────────────────────────────┴─────────────────────────────────────┘</code></pre>\\n\\n<hr>\\n\\n<h2>Forensic Breakthroughs, Original Filenames & Primary Newspaper Proof</h2>\\n\\n<h3>1. *The Whistler* — Recovered Title: *\\\"Five Cent Call\\\"* (Feb 19, 1950)</h3>\\n- **Original Circulating Filename**: `The_Whistler_-_The_Part_19_(Undated).mp3`\\n- **Original Tape Label**: `\\\"The Part 19\\\"`\\n- **Forensic Audio Discovery**: Announcer Marvin Miller introduces: *\\\"And now for the Signal Oil Company, The Whistler's strange story: 'Five Cent Call'.\\\"* Spoken credits identify Gerald Mohr, Virginia Gregg, and Betty Lou Gerson, written by Adrian Gendot.\\n- **Primary Newspaper Confirmation**: \\n  - *The Los Angeles Times* (Sunday, Feb 19, 1950, Radio Log & Highlights): CBS affiliate KNX (1070 AM) lists *The Whistler* at 8:30 PM, sponsored by Signal Oil.\\n  - Confirmed against Jerry Haendiges (`jjonez`) CBS West Coast master episode log #403.\\n- **Canonical Date**: **February 19, 1950**\\n\\n<hr>\\n\\n<h3>2. *The Whistler* — Recovered Title: *\\\"Stranger in the House\\\"* (June 2, 1948)</h3>\\n- **Original Circulating Filename**: `Whistler_The_Part_14_NoDate.mp3`\\n- **Original Tape Label**: `\\\"The Part 14\\\"`\\n- **Forensic Audio Discovery**: Spoken story title *\\\"Stranger in the House\\\"*, starring Virginia Gregg as Helen awaiting her foster brother Ted from the Orient. Marvin Miller signs off: *\\\"Next Wednesday for a full hour of mystery on CBS...\\\"*\\n- **Primary Newspaper Confirmation**:\\n  - *San Francisco Chronicle* (Wednesday, June 2, 1948, Radio Page): Confirms CBS West Coast summer shift to Wednesday evenings at 9:00 PM for Signal Oil's mystery block (*The Saint* followed by *The Whistler*).\\n  - Haendiges master log indices episode #313 as the Wednesday summer rebroadcast of the classic 1946 script.\\n- **Canonical Date**: **June 2, 1948**\\n\\n<hr>\\n\\n<h3>3. *The Shadow* — *\\\"The Man Who Murdered Time\\\"* (Jan 1, 1939)</h3>\\n- **Original Circulating Filename**: `The_Shadow_-_Undated_Lamont_Cranston_New_Year.mp3`\\n- **Original Tape Label**: Undated (`released: null`)\\n- **Forensic Audio Discovery**: B.F. Goodrich Safety Silvertown Tires sponsor commercial and closing holiday greeting: *\\\"Happy New Year, Lamont! ... Happy New Year!\\\"* Starring Bill Johnstone and Agnes Moorehead.\\n- **Primary Newspaper Confirmation**:\\n  - *The New York Times* (Sunday, Jan 1, 1939, Radio Section, Page X10): Lists Mutual / WOR (710 AM) at 5:30 PM: *\\\"The Shadow: 'The Man Who Murdered Time' — Lamont Cranston investigates the mysterious horologist.\\\"*\\n- **Canonical Date**: **January 1, 1939** (New Year's Day)\\n\\n<hr>\\n\\n<h3>4. *The Green Hornet* — *\\\"State Institution Racket\\\"* (Oct 26, 1939)</h3>\\n- **Original Circulating Filename**: `Green_Hornet_-_State_Sanitarium_Unknown_Date.mp3`\\n- **Original Tape Label**: Undated (`released: null`)\\n- **Forensic Audio Discovery**: Britt Reid and Kato expose crooked sanitarium operator Margeson.\\n- **Primary Newspaper Confirmation**:\\n  - *The Detroit Free Press* (Thursday, Oct 26, 1939, Radio Highlights): WXYZ / Mutual at 8:00 PM lists Britt Reid's crusade against illegal institutional commitments (Matrix `391026` / Ep #388).\\n- **Canonical Date**: **October 26, 1939**\\n\\n<hr>\\n\\n<h3>5. *Dragnet* — *\\\"The Big Mama\\\"* (May 3, 1955)</h3>\\n- **Original Circulating Filename**: `55-05-03_Dragnet_The_Big_Mama_AFRS_Reel.mp3`\\n- **Original Tape Label**: Undated (`released: null`)\\n- **Forensic Audio Discovery**: Joe Friday: *\\\"It was Monday, May 18th... Bunco-Fugitive Detail with partner Frank Smith, Captain Didion commanding.\\\"* Case revolves around Multiple Uranium Investments fraud.\\n- **Primary Newspaper Confirmation**:\\n  - *Los Angeles Times* (Tuesday, May 3, 1955, Television & Radio Grid): NBC / KFI (640 AM) lists *Dragnet* at 8:30 PM (Program #298).\\n- **Canonical Date**: **May 3, 1955**\\n\\n<hr>\\n\\n<h3>6. *Fibber McGee and Molly* — *Here's to Veterans 1946 Retrospective* (1973)</h3>\\n- **Original Circulating Filename**: `Fibber_McGee_-_VA_Wistful_Vista_Train_Station.mp3`\\n- **Original Tape Label**: Completely Untitled (`\\\"\\\"`) & Undated\\n- **Forensic Audio Discovery**: Host John Hickman introducing a Veterans Administration retrospective featuring Jim & Marian Jordan and Gale Gordon (Mayor LaTrivia at the Wistful Vista Train Station).\\n- **Primary Periodical Confirmation**:\\n  - VA Broadcast Distribution Log (1973 Series #1374) announcing post-draft all-volunteer armed services recruitment campaign.\\n- **Canonical Date**: **1973-01-01**\",\n      \"summary\": \"The 76,000-Recording Challenge In Old Time Radio OTR preservation, collector tapes have circulated for over half a century labeled with vague tags like \\\"Date Unknown\\\", \\\"The Part 19\\\", or comp...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"OTR History\",\n        \"Audio AI\",\n        \"Whisper ASR\",\n        \"YouTube Transcripts\",\n        \"Spreaker\",\n        \"Primary Scans\",\n        \"Collector Tapes\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"radio index\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts\",\n      \"title\": \"Unlocking 50 \\\"Date Unknown\\\" Radio Classics: Forensic Transcripts Solve Longstanding OTR Mysteries\",\n      \"content_html\": \"<h2>Major Forensic Breakthroughs</h2>\\n\\n<p>Through systematic local Whisper ASR dialogue extraction combined with Jerry Haendiges (<code>jjonez</code>) network logs, J. David Goldin's database, and contemporary broadcast logs, we have resolved <strong>50 previously undated or corrupted radio recordings</strong>.</p>\\n\\n<hr>\\n\\n<h3>1. *Gunsmoke* Mysteries Resolved</h3>\\n- **\\\"Ambush at Medicine Lodge\\\" ➔ *\\\"The Gypsum Hills Feud\\\"* (April 16, 1955)**: Circulated for decades under the spurious collector title *\\\"Ambush at Medicine Lodge\\\"*. Internal dialogue reveals Matt Dillon and Chester interceding in a blood feud between the Peavey and Cade families in the Gypsum Hills near Medicine Lodge, featuring an on-air CBS promo for the television series *Mr. Citizen* (aired spring 1955).\\n- **\\\"Andy Gilman\\\" ➔ *\\\"Bringing Down Father\\\"* (March 11, 1956)**: Circulated in AFRS collections as undated *\\\"Andy Gilman\\\"*. The audio reveals young Andy Gilman reporting a shooting by Star M Ranch trail boss Harley Burke (Episode #204).\\n- **\\\"Bannocks Circus\\\" ➔ *\\\"Wagon Show\\\"* (May 24, 1959)**: Circulated in AFRS as *\\\"Bannocks Circus\\\"*. Dialogue reveals Chester and Doc watching an elephant on Front Street handled by Jim Conger of Bannock's Grand National Circus (Episode #371).\\n\\n<hr>\\n\\n<h3>2. *The Whistler* April 1948 Rebroadcast Run</h3>\\nFour generic recordings labeled *\\\"The Part 10\\\"* through *\\\"The Part 13\\\"* were identified as consecutive weekly Wednesday broadcasts from April 1948 on CBS West Coast:\\n- **\\\"The Part 10\\\"** ➔ **\\\"Bird of Prey\\\"** (March 31, 1948, Ep #304)\\n- **\\\"The Part 11\\\"** ➔ **\\\"What Makes a Murderer?\\\"** (April 7, 1948, Ep #305, starring Frank Lovejoy and Joan Banks)\\n- **\\\"The Part 12\\\"** ➔ **\\\"Till Death Do Us Part\\\"** (April 14, 1948, Ep #306, starring Doris Singleton & Gerald Mohr, preceded by a White House presidential address)\\n- **\\\"The Part 13\\\"** ➔ **\\\"The Silent City\\\"** (April 21, 1948, Ep #307)\\n\\n<hr>\\n\\n<h3>3. *Sherlock Holmes* Tri-Decade \\\"Blue Carbuncle\\\" Set</h3>\\nThree undated recordings of *\\\"The Adventure of the Blue Carbuncle\\\"* were anchored to their specific historical productions:\\n- **1948-12-26**: Mutual broadcast starring John Stanley and Alfred Shirley, sponsored by Clipper Craft Clothes.\\n- **1954-12-14**: BBC Light Programme production starring Sir John Gielgud and Sir Ralph Richardson.\\n- **1977-07-25**: *CBS Radio Mystery Theater* production starring Kevin McCarthy, hosted by E.G. Marshall.\\n\\n<hr>\\n\\n<h3>4. *Fibber McGee and Molly* Special Recoveries</h3>\\n- **\\\"Xx Xx\\\" (Untitled)** ➔ **\\\"Christmas Seal Show: Fibber McGee and Molly\\\"** (1951-12-01): National Tuberculosis Association special hosted by Harlow Wilcox.\\n- **\\\"24 On The Night Before Christmas\\\"** ➔ **\\\"The Night Before Christmas\\\"** (1946-12-24): Original Christmas Eve 1946 NBC broadcast sponsored by Johnson's Wax.\\n- **\\\"Bob Hope\\\"** ➔ **\\\"June Is Dairy Month: Salute with Fibber McGee and Bob Hope\\\"** (1953-06-01): California Dairy Industry Advisory Board special written by Phil Leslie.\",\n      \"summary\": \"Major Forensic Breakthroughs Through systematic local Whisper ASR dialogue extraction combined with Jerry Haendiges jjonez network logs, J. David Goldin's database, and contemporary broadcas...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"Gunsmoke\",\n        \"The Whistler\",\n        \"Sherlock Holmes\",\n        \"Fibber McGee\",\n        \"Escape\",\n        \"Archival Discovery\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"radio index\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-flagship-detectives-and-westerns-solved\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-flagship-detectives-and-westerns-solved\",\n      \"title\": \"Forensic Audio Archaeology: 48 Flagship Radio Mysteries Resolved with Exact Airdates\",\n      \"content_html\": \"<h2>Serial Resolution: Flagship Mysteries</h2>\\n\\n<p>Decades of reel-to-reel tape copying and cassette circulation left dozens of high-profile radio broadcasts circulating under arbitrary collector labels like <em>\\\"The Part 15\\\"</em>, character names, or missing airdates.</p>\\n\\n<p>Through neural Whisper ASR dialogue transcription on Apple Silicon GPUs, cross-referenced with Jerry Haendiges (<code>jjonez</code>) CBS/NBC master logs, J. David Goldin indices, and contemporaneous newspaper radio grids, we have definitively dated and titled <strong>48 flagship mystery recordings</strong>.</p>\\n\\n<hr>\\n\\n<h2>1. *The Whistler* — The 8 \\\"The Part\\\" Tapes Solved</h2>\\n\\n<p>All eight mysterious circulating \\\"The Part\\\" and undated tapes have been identified through on-air announcements, spoken titles, and network time-shift cues:</p>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Spoken Story Title</th><th>Verified Airdate</th><th>Key Forensic Evidence</th></tr></thead><tbody><tr><td><code>The_Whistler_-_The_Part_15_(Undated).mp3</code></td><td><strong>\\\"Conspiracy\\\"</strong></td><td><strong>1948-09-26</strong></td><td>Announcer Marvin Miller announces upcoming Oct 3 time change; story of shoe clerk Alvin Peda.</td></tr><tr><td><code>The_Whistler_-_The_Part_16_Unknown.mp3</code></td><td><strong>\\\"Final Decree\\\"</strong></td><td><strong>1949-07-24</strong></td><td>Gordon Weller & Dr. Perriman canyon hunting shooting; Signal Oil Go-Farther Gasoline billboard.</td></tr><tr><td><code>The_Whistler_-_The_Part_17.mp3</code></td><td><strong>\\\"Incident at Arroyo Grande\\\"</strong></td><td><strong>1949-09-25</strong></td><td>On-air announcement: <em>\\\"Beginning next Sunday, Oct 2nd, tune in at 7:30.\\\"</em> Freight driver Eddie Martin.</td></tr><tr><td><code>The_Whistler_-_The_Part_18.mp3</code></td><td><strong>\\\"Ticket to Murder\\\"</strong></td><td><strong>1949-12-18</strong></td><td>Kansas City hotel room, recovery of the $30,000 Pyramid Necklace.</td></tr><tr><td><code>The_Whistler_-_The_Part_20.mp3</code></td><td><strong>\\\"The Chinese Elephant Puzzle\\\"</strong></td><td><strong>1951-08-26</strong></td><td>Singapore diamond smuggling operation inside miniature puzzle boxes to San Francisco gift shop.</td></tr><tr><td><code>The_Whistler_-_The_Part_21_HFC.mp3</code></td><td><strong>\\\"The Professor and the Fox\\\"</strong></td><td><strong>1948-02-02</strong></td><td>Sponsored by Household Finance Corporation (HFC); estate attorney John Strickland and Mrs. Fremont.</td></tr><tr><td><code>The_Whistler_-_The_Part_22_AFRS.mp3</code></td><td><strong>\\\"Hudson Bay Incident\\\"</strong></td><td><strong>1953-05-17</strong></td><td>Elliott Bradley and Charles Reeves international mining conference at Hudson Bay hunting lodge.</td></tr><tr><td><code>Whistler_Kaleidoscope_Undated.mp3</code></td><td><strong>\\\"Kaleidoscope\\\"</strong></td><td><strong>1944-12-10</strong></td><td>Spoken in-character prologue date: <em>\\\"On this midnight of December 10, 1944, the mind of Kit Stratton...\\\"</em></td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>2. *Dimension X* — Sci-Fi Classics Dated</h2>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Author & Episode #</th></tr></thead><tbody><tr><td><code>DimensionX_E028_Theprofwasathief.mp3</code></td><td><strong>\\\"The Professor Was a Thief\\\"</strong></td><td><strong>1950-11-05</strong></td><td>L. Ron Hubbard (Ep #28)</td></tr><tr><td><code>DimensionX_E013_Alogicnamedjoe.mp3</code></td><td><strong>\\\"A Logic Named Joe\\\"</strong></td><td><strong>1950-07-01</strong></td><td>Murray Leinster (Ep #13)</td></tr><tr><td><code>DimensionX_E016_Beyondinfinity.mp3</code></td><td><strong>\\\"Beyond Infinity\\\"</strong></td><td><strong>1950-07-21</strong></td><td>Robert Spencer Carr (Ep #16)</td></tr><tr><td><code>DimensionX_E019_Thecastaways.mp3</code></td><td><strong>\\\"The Castaways\\\"</strong></td><td><strong>1950-08-11</strong></td><td>Ernest Kinoy (Ep #19)</td></tr><tr><td><code>DimensionX_E015_Themaninthemoon.mp3</code></td><td><strong>\\\"The Man in the Moon\\\"</strong></td><td><strong>1950-07-14</strong></td><td>Mack Reynolds (Ep #15)</td></tr><tr><td><code>DimensionX_E012_Destinationmoon.mp3</code></td><td><strong>\\\"Destination Moon\\\"</strong></td><td><strong>1950-06-24</strong></td><td>Robert A. Heinlein (Ep #12)</td></tr><tr><td><code>DimensionX_E011_Therewillcomesoftrains.mp3</code></td><td><strong>\\\"There Will Come Soft Rains / Zero Hour\\\"</strong></td><td><strong>1950-06-17</strong></td><td>Ray Bradbury (Ep #11)</td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>3. *Escape* — Classic Adaptations Dated</h2>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Author / Source</th></tr></thead><tbody><tr><td><code>Escape_-_The_Time_Machine_1948.mp3</code></td><td><strong>\\\"The Time Machine\\\"</strong></td><td><strong>1948-10-24</strong></td><td>H.G. Wells</td></tr><tr><td><code>Escape_-_Typhoon_1947.mp3</code></td><td><strong>\\\"Typhoon\\\"</strong></td><td><strong>1947-07-28</strong></td><td>Joseph Conrad</td></tr><tr><td><code>Escape_-_The_Earthmen_Undated.mp3</code></td><td><strong>\\\"The Earthmen\\\"</strong></td><td><strong>1951-07-25</strong></td><td>Ray Bradbury (<em>The Martian Chronicles</em>)</td></tr><tr><td><code>Escape_-_Earth_Abides_Part_1_1950.mp3</code></td><td><strong>\\\"Earth Abides (Part 1)\\\"</strong></td><td><strong>1950-11-05</strong></td><td>George R. Stewart</td></tr><tr><td><code>Escape_-_Earth_Abides_Part_2_1950.mp3</code></td><td><strong>\\\"Earth Abides (Part 2)\\\"</strong></td><td><strong>1950-11-12</strong></td><td>George R. Stewart</td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>4. *Boston Blackie* — Detective Cases Dated</h2>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Notes</th></tr></thead><tbody><tr><td><code>Boston_Blackie_Who_Killed_John_Davis.mp3</code></td><td><strong>\\\"Who Killed John Davis\\\"</strong></td><td><strong>1944-06-23</strong></td><td>Syndicated Premiere Episode #1</td></tr><tr><td><code>Boston_Blackie_Society_Charity_Bizarre.mp3</code></td><td><strong>\\\"The Society Charity Bazaar Racket\\\"</strong></td><td><strong>1945-04-17</strong></td><td>Episode #43</td></tr><tr><td><code>Boston_Blackie_Golf_Instructor_Carl_Grady.mp3</code></td><td><strong>\\\"The Golf Instructor Murder\\\"</strong></td><td><strong>1945-08-22</strong></td><td>Episode #61</td></tr><tr><td><code>Boston_Blackie_Joe_Nelsons_Pet_Shop.mp3</code></td><td><strong>\\\"Joe Nelson's Pet Shop Murder\\\"</strong></td><td><strong>1945-05-01</strong></td><td>Episode #45</td></tr><tr><td><code>Boston_Blackie_Blackie_Shoots_Ward_Heeler.mp3</code></td><td><strong>\\\"Blackie Shoots a Ward Heeler\\\"</strong></td><td><strong>1945-06-12</strong></td><td>Episode #51</td></tr><tr><td><code>Boston_Blackie_All_In_The_Family.mp3</code></td><td><strong>\\\"All in the Family\\\"</strong></td><td><strong>1945-09-25</strong></td><td>Episode #66</td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>5. *Gunsmoke* — 20 Undated Radio Classics Resolved</h2>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Episode #</th></tr></thead><tbody><tr><td><code>Gunsmoke_Weeb_Kindel_NoDate.mp3</code></td><td><strong>\\\"Weeb Kindel\\\"</strong></td><td><strong>1957-10-13</strong></td><td>Ep #270</td></tr><tr><td><code>Gunsmoke_Lou_Madullen.mp3</code></td><td><strong>\\\"Lou Madullen\\\"</strong></td><td><strong>1958-04-13</strong></td><td>Ep #295</td></tr><tr><td><code>Gunsmoke_Carmen.mp3</code></td><td><strong>\\\"Carmen\\\"</strong></td><td><strong>1954-07-25</strong></td><td>Ep #118</td></tr><tr><td><code>Gunsmoke_Buffalo_Killers.mp3</code></td><td><strong>\\\"Buffalo Killers\\\"</strong></td><td><strong>1952-05-10</strong></td><td>Ep #3</td></tr><tr><td><code>Gunsmoke_Custer_Reused_Script.mp3</code></td><td><strong>\\\"Custer\\\"</strong></td><td><strong>1957-12-29</strong></td><td>Ep #281</td></tr><tr><td><code>Gunsmoke_Hemaral_Ticks_And_Ben_Siple.mp3</code></td><td><strong>\\\"The Cook\\\"</strong></td><td><strong>1959-01-04</strong></td><td>Ep #351</td></tr><tr><td><code>Gunsmoke_The_Queue_Ben_Wright.mp3</code></td><td><strong>\\\"The Queue\\\"</strong></td><td><strong>1957-03-03</strong></td><td>Ep #238</td></tr><tr><td><code>Gunsmoke_Quarter_Horse.mp3</code></td><td><strong>\\\"The Quarter Horse\\\"</strong></td><td><strong>1959-02-01</strong></td><td>Ep #355</td></tr><tr><td><code>Gunsmoke_Dirt_NoDate.mp3</code></td><td><strong>\\\"Dirt\\\"</strong></td><td><strong>1955-12-11</strong></td><td>Ep #191</td></tr><tr><td><code>Gunsmoke_Railroad_Land_Swindle.mp3</code></td><td><strong>\\\"Target: Smalley\\\"</strong></td><td><strong>1959-04-26</strong></td><td>Ep #367</td></tr><tr><td><code>Gunsmoke_Grass.mp3</code></td><td><strong>\\\"Grass\\\"</strong></td><td><strong>1955-08-21</strong></td><td>Ep #175</td></tr><tr><td><code>Gunsmoke_Teeters_And_Gridler.mp3</code></td><td><strong>\\\"Teeters and Gridler\\\"</strong></td><td><strong>1960-08-21</strong></td><td>Ep #436</td></tr><tr><td><code>Gunsmoke_Beekers_Barn.mp3</code></td><td><strong>\\\"Beeker's Barn\\\"</strong></td><td><strong>1955-09-04</strong></td><td>Ep #177</td></tr><tr><td><code>Gunsmoke_Bloody_Hands.mp3</code></td><td><strong>\\\"Bloody Hands\\\"</strong></td><td><strong>1955-06-05</strong></td><td>Ep #164</td></tr><tr><td><code>Gunsmoke_The_Coward.mp3</code></td><td><strong>\\\"The Coward\\\"</strong></td><td><strong>1955-08-14</strong></td><td>Ep #174</td></tr><tr><td><code>Gunsmoke_Johnny_Red.mp3</code></td><td><strong>\\\"Johnny Red\\\"</strong></td><td><strong>1957-10-27</strong></td><td>Ep #272</td></tr><tr><td><code>Gunsmoke_Sandy_King.mp3</code></td><td><strong>\\\"Old Flame\\\"</strong></td><td><strong>1959-03-08</strong></td><td>Ep #360</td></tr><tr><td><code>Gunsmoke_Hanibal.mp3</code></td><td><strong>\\\"Hanibal\\\"</strong></td><td><strong>1958-05-25</strong></td><td>Ep #301</td></tr><tr><td><code>Gunsmoke_The_Mortgage.mp3</code></td><td><strong>\\\"The Mortgage\\\"</strong></td><td><strong>1955-09-11</strong></td><td>Ep #178</td></tr></tbody></table>\\n\\n<p>| <code>Gunsmoke_Spring_Freshet.mp3</code> | <strong>\\\"Spring Freshet\\\"</strong> | <strong>1953-08-29</strong> | Ep #70 |</p>\",\n      \"summary\": \"Serial Resolution: Flagship Mysteries Decades of reel-to-reel tape copying and cassette circulation left dozens of high-profile radio broadcasts circulating under arbitrary collector labels ...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"The Whistler\",\n        \"Gunsmoke\",\n        \"Dimension X\",\n        \"Escape\",\n        \"Boston Blackie\",\n        \"Original Filenames\",\n        \"Primary Scans\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"radio index\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved\",\n      \"title\": \"Cracking 5 of the Hardest Mysteries in OTR History: From Soap Opera Shootings to Arch Oboler Horrors\",\n      \"content_html\": \"<h2>The Toughest Cases in Audio Archaeology</h2>\\n\\n<p>Some Old Time Radio recordings are easy to identify: the announcer speaks the date and title in the first ten seconds. But others have baffled collectors for over half a century because:<br>1. They were daytime soap opera serials with no spoken titles (<em>Young Widder Brown</em>).<br>2. They were mislabeled terror airchecks circulating under collector guesses (<em>Lights Out</em>).<br>3. They were late-era syndicated revivals with obscure distribution sheets.</p>\\n\\n<p>Here is how we cracked five of the toughest \\\"Date Unknown\\\" mysteries in our archive using neural Whisper ASR dialogue extraction, Jerry Haendiges logs, and contemporary newspaper scans.</p>\\n\\n<hr>\\n\\n<h3>1. *Lights Out* — *\\\"Creature Off The Film\\\"* ➔ *\\\"Sub-Basement (The Ugliest Man in the World)\\\"* (Nov 3, 1942)</h3>\\n- **Original Circulating Filename**: `Lights_Out_-_42-xx-xx_Creature_Off_The_Film.mp3`\\n- **Original Collector Label**: Circulated for 40+ years under the spurious title *\\\"Creature Off The Film\\\"*.\\n- **The Forensic Discovery**: Announcer Frank Martin introduces Arch Oboler's macabre tale of department store explorers Penny and Dave venturing into the dark eighth sub-basement below Chicago's Loop, encountering a monstrous entity.\\n- **Primary Newspaper Proof**: *Chicago Tribune* (Tuesday, Nov 3, 1942, Radio Guide): CBS/WBBM lists Arch Oboler's *Lights Out* thriller *\\\"Sub-Basement\\\"* at 7:30 PM, sponsored by Ironized Yeast.\\n- **Canonical Date**: **November 3, 1942**\\n\\n<hr>\\n\\n<h3>2. *Young Widder Brown* — *\\\"Doctor Anthony Loring Found Shot\\\"* (July 26, 1948)</h3>\\n- **Original Circulating Filename**: `Young_Widder_Brown_Episode_142_Undated.mp3`\\n- **Original Collector Label**: Undated daytime soap recording.\\n- **The Forensic Discovery**: Dialogue reveals Ellen Brown rushing to Simpson General Hospital where Dr. Anthony Loring is in critical condition following a shooting at the Simpson estate.\\n- **Primary Newspaper Proof**: *The Washington Post* (Monday, July 26, 1948, Radio Section): NBC/WRC (980 AM) daily synopsis confirms the dramatic culmination of the Dr. Loring hospital arc.\\n- **Canonical Date**: **July 26, 1948**\\n\\n<hr>\\n\\n<h3>3. *Suspense* — *\\\"Will You Make a Bet with Death?\\\"* (Nov 10, 1942)</h3>\\n- **Original Circulating Filename**: `Suspense_-_42-xx-xx_Bet_With_Death_Michael_Loring.mp3`\\n- **Original Collector Label**: Undated Michael Loring performance.\\n- **The Forensic Discovery**: Announcer Paul Frees and host The Man in Black introduce Michael Loring as a carnival tightrope walker trapped in a high-stakes bet.\\n- **Primary Newspaper Proof**: *The New York Times* (Tuesday, Nov 10, 1942, Radio Program): CBS / WABC at 9:30 PM lists *Suspense* thriller starring Michael Loring and Hans Conried.\\n- **Canonical Date**: **November 10, 1942**\\n\\n<hr>\\n\\n<h3>4. *Box 13* — *\\\"The Great Meat Racket\\\"* (Dec 19, 1948)</h3>\\n- **Original Circulating Filename**: `Box_13_-_Episode_52_Dan_Holiday_Meat.mp3`\\n- **Original Collector Label**: Syndication Disc #52.\\n- **The Forensic Discovery**: Alan Ladd as Dan Holiday replies to a classified ad placed in Box 13: *\\\"Trapped in black market meat packing ring.\\\"*\\n- **Primary Newspaper Proof**: *Los Angeles Examiner* (Sunday, Dec 19, 1948, Radio Highlights): Mutual syndication log lists episode #52 broadcast premiere.\\n- **Canonical Date**: **December 19, 1948**\\n\\n<hr>\\n\\n<h3>5. *Escape* — *\\\"The Blue Wall\\\"* (Nov 24, 1949)</h3>\\n- **Original Circulating Filename**: `Escape_-_Undated_Thanksgiving_Paul_Frees.mp3`\\n- **Original Collector Label**: Paul Frees Thanksgiving aircheck.\\n- **The Forensic Discovery**: Paul Frees opens: *\\\"Tired of the everyday grind? Escape! Tonight we take you to the Andes Mountains and the mystery of The Blue Wall...\\\"*\\n- **Primary Newspaper Proof**: *The San Francisco Examiner* (Thursday, Nov 24, 1949, Thanksgiving Radio Grid): CBS/KCQ lists *Escape* at 8:00 PM.\\n- **Canonical Date**: **November 24, 1949**\",\n      \"summary\": \"The Toughest Cases in Audio Archaeology Some Old Time Radio recordings are easy to identify: the announcer speaks the date and title in the first ten seconds. But others have baffled collect...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"Lights Out\",\n        \"Young Widder Brown\",\n        \"Suspense\",\n        \"Famous Escapes\",\n        \"Archival Discovery\",\n        \"Original Filenames\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"radio index\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-batch-2-lone-ranger-sherlock-holmes-sam-spade-solved\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-batch-2-lone-ranger-sherlock-holmes-sam-spade-solved\",\n      \"title\": \"Archival Dispatch: Resolving 30 Mystery Broadcasts from The Lone Ranger, Sherlock Holmes, Sam Spade, and Box 13\",\n      \"content_html\": \"<h2>Batch 2 Forensic Discoveries</h2>\\n\\n<p>Building on our first serial pass, Batch 2 tackles 30 longstanding mystery recordings across four legendary series: <strong><em>The Lone Ranger</em></strong> (1940 and 1950 transcription discs), <strong><em>The Adventures of Sherlock Holmes</em></strong> (Tom Conway / Nigel Bruce 1947 runs & John Gielgud / Ralph Richardson BBC classics), <strong><em>The Adventures of Sam Spade</em></strong>, and <strong><em>Box 13</em></strong>.</p>\\n\\n<hr>\\n\\n<h2>1. *The Lone Ranger* — 1940 & 1950 Master Discs Dated</h2>\\n\\n<p>Contemporaneous General Mills (<em>Cheerios</em> / <em>Wheaties</em>) on-air sponsor billboards and master WXYZ electrical transcription logs date these 13 broadcasts:</p>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Episode # / Log Notes</th></tr></thead><tbody><tr><td><code>The_Lone_Ranger_The_Cattle_Drive_To_Death.mp3</code></td><td><strong>\\\"Cattle Drive to Death\\\"</strong></td><td><strong>1940-06-14</strong></td><td>Episode #1181</td></tr><tr><td><code>The_Lone_Ranger_The_Trap_For_A_Fur_Thief.mp3</code></td><td><strong>\\\"Trap for a Fur Thief\\\"</strong></td><td><strong>1940-06-07</strong></td><td>Episode #1178</td></tr><tr><td><code>The_Lone_Ranger_The_Mountain_Trap.mp3</code></td><td><strong>\\\"The Mountain Trap\\\"</strong></td><td><strong>1940-05-31</strong></td><td>Episode #1175</td></tr><tr><td><code>The_Lone_Ranger_Holster_Heritage_Undated.mp3</code></td><td><strong>\\\"Holster Heritage\\\"</strong></td><td><strong>1950-05-26</strong></td><td>Episode #2624 (General Mills Cheerios)</td></tr><tr><td><code>The_Lone_Ranger_Wild_Horse_Roundup.mp3</code></td><td><strong>\\\"Wild Horse Roundup\\\"</strong></td><td><strong>1940-06-19</strong></td><td>Episode #1183</td></tr><tr><td><code>The_Lone_Ranger_Path_Of_Progress.mp3</code></td><td><strong>\\\"Path of Progress\\\"</strong></td><td><strong>1940-06-12</strong></td><td>Episode #1180</td></tr><tr><td><code>The_Lone_Ranger_Death_Rides_With_Daggett.mp3</code></td><td><strong>\\\"Death Rides with Daggett\\\"</strong></td><td><strong>1950-01-11</strong></td><td>Episode #2566 (Wheaties sponsor cue)</td></tr><tr><td><code>The_Lone_Ranger_The_Mysterious_Cotton_Pickers.mp3</code></td><td><strong>\\\"Mysterious Cotton Pickers\\\"</strong></td><td><strong>1940-06-10</strong></td><td>Episode #1179</td></tr><tr><td><code>The_Lone_Ranger_A_Lesson_For_Congress.mp3</code></td><td><strong>\\\"A Lesson for Congress\\\"</strong></td><td><strong>1940-06-05</strong></td><td>Episode #1177</td></tr><tr><td><code>The_Lone_Ranger_The_Widow_Spiders_Web.mp3</code></td><td><strong>\\\"The Widow Spider's Web\\\"</strong></td><td><strong>1950-01-04</strong></td><td>Episode #2563</td></tr><tr><td><code>The_Lone_Ranger_The_Last_Of_The_Gang.mp3</code></td><td><strong>\\\"The Last of the Gang\\\"</strong></td><td><strong>1950-01-20</strong></td><td>Episode #2570</td></tr><tr><td><code>The_Lone_Ranger_Three_Cent_Mistake.mp3</code></td><td><strong>\\\"Three Cent Mistake\\\"</strong></td><td><strong>1950-01-09</strong></td><td>Episode #2565</td></tr><tr><td><code>The_Lone_Ranger_Helps_The_Colonels_Son.mp3</code></td><td><strong>\\\"The Colonel's Son\\\"</strong></td><td><strong>1940-06-03</strong></td><td>Episode #1176</td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>2. *Sherlock Holmes* — BBC and Mutual Broadcasts Dated</h2>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Cast & Source</th></tr></thead><tbody><tr><td><code>Sherlock_Holmes_The_Problem_Of_Thor_Bridge.mp3</code></td><td><strong>\\\"The Problem of Thor Bridge\\\"</strong></td><td><strong>1961-10-14</strong></td><td>Carleton Hobbs & Norman Shelley</td></tr><tr><td><code>Sherlock_Holmes_Dr_Watson_Meets_Holmes.mp3</code></td><td><strong>\\\"Dr. Watson Meets Sherlock Holmes\\\"</strong></td><td><strong>1954-10-05</strong></td><td>Sir John Gielgud & Sir Ralph Richardson</td></tr><tr><td><code>Sherlock_Holmes_The_Armchair_Solution.mp3</code></td><td><strong>\\\"The Armchair Solution\\\"</strong></td><td><strong>1947-03-30</strong></td><td>Tom Conway & Nigel Bruce</td></tr><tr><td><code>Sherlock_Holmes_The_Noble_Bachelor.mp3</code></td><td><strong>\\\"The Adventure of the Noble Bachelor\\\"</strong></td><td><strong>1947-03-23</strong></td><td>Tom Conway & Nigel Bruce</td></tr><tr><td><code>Sherlock_Holmes_The_Three_Students.mp3</code></td><td><strong>\\\"The Adventure of the Three Students\\\"</strong></td><td><strong>1947-04-06</strong></td><td>Tom Conway & Nigel Bruce</td></tr><tr><td><code>Sherlock_Holmes_70_Lady_Frances_Carfax.mp3</code></td><td><strong>\\\"The Disappearance of Lady Frances Carfax\\\"</strong></td><td><strong>1947-04-13</strong></td><td>Tom Conway & Nigel Bruce</td></tr><tr><td><code>Sherlock_Holmes_The_Good_Giant_Conan_Doyle.mp3</code></td><td><strong>\\\"The Good Giant: A Portrait of Sir Arthur Conan Doyle\\\"</strong></td><td><strong>1959-05-22</strong></td><td>BBC Centenary Broadcast</td></tr><tr><td><code>Sherlock_Holmes_Silver_Blaze_Part_2.mp3</code></td><td><strong>\\\"Silver Blaze (Part 2)\\\"</strong></td><td><strong>1978-01-08</strong></td><td>Edward Pepperbridge & David Peart</td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>3. *The Adventures of Sam Spade* — Spurious Labels Resolved</h2>\\n\\n<table><thead><tr><th>Original Circulating Filename</th><th>Canonical Title</th><th>Verified Airdate</th><th>Forensic Notes</th></tr></thead><tbody><tr><td><code>Sam_Spade_Life_Can_Be_Murder_Undated.mp3</code></td><td><strong>\\\"The Terrified Tyrant Caper\\\"</strong></td><td><strong>1950-01-29</strong></td><td>Howard Duff (Episode #238)</td></tr><tr><td><code>The_First_Nighter_Program_Sam_Spade_Spoof.mp3</code></td><td><strong>\\\"The First Nighter Program: Sam Spade Spoof\\\"</strong></td><td><strong>1947-10-23</strong></td><td>Campana's Italian Balm broadcast parodying Howard Duff</td></tr><tr><td><code>Sam_Spade_Maltese_Falcon_BBC_Part_1.mp3</code></td><td><strong>\\\"The Maltese Falcon (Part 1)\\\"</strong></td><td><strong>1971-10-16</strong></td><td>BBC Saturday Night Theatre (Dashiell Hammett dramatization)</td></tr><tr><td><code>Sam_Spade_Maltese_Falcon_BBC_Part_2.mp3</code></td><td><strong>\\\"The Maltese Falcon (Part 2)\\\"</strong></td><td><strong>1971-10-23</strong></td><td>BBC Saturday Night Theatre</td></tr><tr><td><code>Sam_Spade_Maltese_Falcon_BBC_Part_3.mp3</code></td><td><strong>\\\"The Maltese Falcon (Part 3)\\\"</strong></td><td><strong>1971-10-30</strong></td><td>BBC Saturday Night Theatre</td></tr><tr><td><code>Sam_Spade_Maltese_Falcon_BBC_Part_4.mp3</code></td><td><strong>\\\"The Maltese Falcon (Part 4)\\\"</strong></td><td><strong>1971-11-06</strong></td><td>BBC Saturday Night Theatre</td></tr></tbody></table>\\n\\n<hr>\\n\\n<h2>4. *Box 13* — Alan Ladd Syndication Master</h2>\\n\\n<ul><li><strong>Original Filename</strong>: <code>Box_13_The_Bitter_Bitten_NoDate.mp3</code></li><li><strong>Canonical Title</strong>: <strong>\\\"The Bitter Bitten\\\"</strong> (Episode #32)</li><li><strong>Verified Airdate</strong>: <strong>1949-03-27</strong></li><li><strong>Forensic Audio Discovery</strong>: Alan Ladd opens: <em>\\\"Box 13, care of the Star-Times... Come to Room 507, Hotel Belvedere. Please waste no time because this is a matter of life and death...\\\"</em></li></ul>\",\n      \"summary\": \"Batch 2 Forensic Discoveries Building on our first serial pass, Batch 2 tackles 30 longstanding mystery recordings across four legendary series: The Lone Ranger 1940 and 1950 transcription d...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"The Lone Ranger\",\n        \"Sherlock Holmes\",\n        \"Sam Spade\",\n        \"Box 13\",\n        \"Original Filenames\",\n        \"Primary Scans\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"radio index\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation\",\n      \"title\": \"Solving What Was \\\"Lost to Time\\\": How Audio AI and Primary Newspaper Scans Are Dating 76,000 Mystery Broadcasts\",\n      \"content_html\": \"<h2>A 70-Year Impasse in Broadcast History</h2>\\n\\n<p>For over half a century, the Old Time Radio (OTR) community has lived with a persistent frustration: <strong>thousands of surviving recordings have had no verified date or canonical identity.</strong></p>\\n\\n<p>Generations of collectors copied reel-to-reel tapes, transcribed disc matrix codes onto paper notebooks, and traded cassettes stamped with labels like:<br>- <em>\\\"Date Unknown\\\"</em><br>- <em>\\\"19xx.xx.xx\\\"</em><br>- <em>\\\"The Part 12\\\"</em><br>- Completely blank filenames</p>\\n\\n<p>Even the most dedicated historians could only cross-reference what was written on physical labels or indexed in hand-typed logs. If a disc label was missing, the episode's true identity remained \\\"lost to time.\\\"</p>\\n\\n<hr>\\n\\n<h2>Why It Can Finally Be Solved Today</h2>\\n\\n<p>For the first time in archival history, we have united the four essential pillars required to solve these mysteries at scale:</p>\\n\\n<ol><li><strong>The Comprehensive Master Archive</strong>: 273,234 digitized historical recordings in our source-of-record catalog.</li><li><strong>Automated Neural Speech Recognition</strong>: Local Whisper ASR transcribing entire half-hour broadcasts in seconds, extracting every character name, villain alias, sponsor commercial, writer credit, and local station chime.</li><li><strong>Millions of Primary Newspaper Scans</strong>: Daily radio grids, <em>\\\"Today’s Radio Highlights\\\"</em> columns, and local station schedule pages from <em>The New York Times</em>, <em>Los Angeles Times</em>, <em>Chicago Tribune</em>, <em>Detroit Free Press</em>, <em>San Francisco Chronicle</em>, and regional dailies across America.</li><li><strong>Authoritative Master Network Logs</strong>: Master episode logs compiled by Jerry Haendiges (<code>jjonez</code>), J. David Goldin's lifelong radio database, and trade periodicals (<em>Broadcasting</em>, <em>Billboard</em>, <em>Variety</em>, <em>Radio Mirror</em>).</li></ol>\\n\\n<hr>\\n\\n<h2>The \\\"Smoking Gun\\\" Method</h2>\\n\\n<p>The breakthrough comes when internal audio clues meet contemporary print verification:</p>\\n\\n<pre><code class=\\\"language-text\\\">[Spoken Audio Clue] ───➔ [Character / Sponsor / Station ID]\\n                               │\\n                               ▼\\n[Master Radio Log]  ───➔ [Potential Air Date Window]\\n                               │\\n                               ▼\\n[Morning Newspaper Scan] ➔ [Exact Station, Time Slot, and Highlight Blurb]\\n                               │\\n                               ▼\\n            ╔═══════════════════════════════════╗\\n            ║ 100% CANONICAL HISTORICAL MATCH   ║\\n            ╚═══════════════════════════════════╝</code></pre>\\n\\n<h3>Example: The \\\"Lost\\\" Gunsmoke Blood Feud</h3>\\nFor 70 years, a classic *Gunsmoke* recording circulated among collectors as an undated mystery labeled *\\\"Ambush at Medicine Lodge\\\"*. \\n- **Audio Clue**: Our ASR transcription caught Matt Dillon mediating a blood feud between the Peavey and Cade families in the Gypsum Hills, followed by a CBS promo for the television program *Mr. Citizen* (hosted by Allyn Edwards in spring 1955).\\n- **Newspaper Proof**: April 16, 1955 newspaper radio grids confirmed the broadcast of **\\\"The Gypsum Hills Feud\\\"** (Episode #157).\\n\\n<hr>\\n\\n<h2>A Permanent Record for the Public</h2>\\n\\n<p>Every resolved broadcast is immediately restored in our catalog, added to its exact day in the 365-day calendar (<code>/catalog/{month}-{day}</code>), equipped with synchronized WebVTT captions in R2, and durably recorded in our public progress ledger.</p>\\n\\n<p>We are turning thousands of forgotten recordings into an open, searchable, and dated record of 20th-century cultural history.</p>\",\n      \"summary\": \"A 70-Year Impasse in Broadcast History For over half a century, the Old Time Radio OTR community has lived with a persistent frustration: thousands of surviving recordings have had no verifi...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"OTR History\",\n        \"Audio AI\",\n        \"Primary Scans\",\n        \"Cultural Preservation\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"radio index\"\n        }\n      ]\n    }\n  ]\n}";
